diagrams.source:
flowchart TD
  a[effort_for agent executor] --> b{effort has key for executor.tier_table?}
  b -->|yes| c[Return that Effort]
  b -->|no| d{effort has native key?}
  d -->|yes| e[Return native Effort]
  d -->|no| f[Return Effort High]

flowchart TD
  m[Mention m in file a] --> t{Qualifier}
  t -->|self or this| s1[Definitions in file a]
  t -->|Name Q| q1{A definition has container Q?}
  q1 -->|yes| q2[Own file first else nearest]
  q1 -->|no| q3{A file module name equals Q?}
  q3 -->|yes| q4[Nearest top-level definitions]
  q3 -->|no| mem
  t -->|none| mem{Member after dot or arrow?}
  mem -->|yes| mm[Members whose container the file names]
  mem -->|no| own{File defines the name?}
  own -->|yes| o1[Own definitions]
  own -->|no| vis[Bare kinds visible by tier then nearest with cap]

flowchart TD
s[Step from a planner rule] --> held{"Spawn, command, or autofix in a created project whose init has not ended"}
held -->|yes| drop1[Dropped]
held -->|no| sp{Is it a Spawn}
sp -->|no| dedupe
sp -->|yes| wake{"Run waiting for a message under this purpose key"}
wake -->|"waiting, no message"| drop2[Dropped]
wake -->|message ready| res[Set resumes to the waiting run]
wake -->|none| rs["Set resumes from resume_from, else continues from continuation"]
res --> busy
rs --> busy{"Conversation has a live run"}
busy -->|yes| drop3[Dropped]
busy -->|no| bud{"Spent at or above budget plus raises"}
bud -->|yes| gate["Open BudgetReached once, drop the spawn"]
bud -->|no| dedupe["Add unless the same key is queued"]

flowchart TD
    A[Model response] --> B{stop reason}
    B -->|PauseTurn| A2[next turn unchanged]
    B -->|Refusal| F1[fail with category]
    B -->|MaxTokens and no tools| C{continues below 3}
    C -->|yes| C1[add continue message]
    C -->|no| F2[fail output limit]
    B -->|other| D{has tool calls}
    D -->|no| E{already reminded}
    E -->|no| E1[send submit reminder]
    E -->|yes| OK[finish with final text]
    D -->|yes| G[run_tools]
    G --> H{submit accepted}
    H -->|yes| OK2[finish with submit payload]
    H -->|no| A2

flowchart TD
  start["decide(cfg)"] --> off{"mode is off?"}
  off -- yes --> u0["Unsandboxed(None)"]
  off -- no --> have{"backend() found one?"}
  have -- yes --> sand["Sandboxed(backend)"]
  have -- no --> auto{"mode is auto?"}
  auto -- yes --> u1["Unsandboxed(Some(message))"]
  auto -- no --> err["Err: required but not available"]

flowchart TD
  ord["Profile::ordered"] --> each{"Is the rule ReadOnly?"}
  each -- no --> keep["Keep the rule"]
  each -- yes --> hid{"Nearest mounted ancestor is Hidden and not revealed?"}
  hid -- yes --> drop["Drop the rule"]
  hid -- no --> ex{"Path exists?"}
  ex -- yes --> keep
  ex -- no --> wr{"Nearest ancestor is a self-bound Writable?"}
  wr -- yes --> ph["Create placeholder, keep the rule"]
  wr -- no --> drop
  keep --> pins["Pin directories between a writable bind and a mount inside it"]
  ph --> pins

flowchart TD
  a[Request] --> b{Host allowed?}
  b -->|no| c[421 host not allowed]
  b -->|yes| d{Private name set and path not internal?}
  d -->|yes| e["API 421, page 307 to private name"]
  d -->|no| f{Path starts with /internal/?}
  f -->|yes| g{"Local peer and no Origin or Sec-Fetch-Site?"}
  g -->|no| h[403]
  f -->|no| i{API path or /ws?}
  g -->|yes| j[Run handler]
  i -->|no| j
  i -->|yes| k{"Origin and fetch metadata allowed?"}
  k -->|no| h
  k -->|yes| l{"Exchange path or valid cookie?"}
  l -->|no| m[401]
  l -->|yes| j
  j --> n[Add security headers]

flowchart TD
  a[unlock] --> b{OSTRA_MASTER_KEY_FILE set?}
  b -->|yes| c[Use that file key]
  b -->|no| d{Recorded backend is file?}
  d -->|yes| e[Use data dir master.key]
  d -->|no| f{Keychain holds the key?}
  f -->|yes| g[Use keychain key]
  f -->|no entry| h{Keychain keeps a new key?}
  h -->|yes| g
  h -->|no| e
  f -->|unreachable| i{Backend recorded as keychain?}
  i -->|yes| j[Stop startup with unlock message]
  i -->|no| e

flowchart TD
  a[Parse URL] --> b{Scheme is http or https}
  b -->|no| e1[Error: only http and https]
  b -->|yes| c{Private IP literal without allow rule}
  c -->|yes| e2[Error: add WebFetch domain rule]
  c -->|no| d[GET with PublicResolver]
  d --> f{Resolves to public address}
  f -->|no| e2
  f -->|yes| g{Redirect to another host}
  g -->|yes| h[Return the new URL to fetch]
  g -->|no| i[Read up to 5 MiB and convert to text]
  i --> j[Truncate to 100000 characters]

flowchart TD
  href[Markdown link href] --> web{"Starts with http, https or mailto?"}
  web -->|yes| ext[External link]
  web -->|no| scheme{"Any other scheme?"}
  scheme -->|yes| plain[Plain text]
  scheme -->|no| path{"Path part empty?"}
  path -->|yes| own[Anchor on this page or another page]
  path -->|no| file{"Resolved file is a docs page source?"}
  file -->|yes| page[Internal link to that page]
  file -->|no| url{"fileUrl returns a URL?"}
  url -->|yes| gh[External link to the file]
  url -->|no| plain
